import React, { createContext, useContext, useState, useEffect } from 'react';
import { toast } from 'react-hot-toast';
import { getApiUrl } from '../config/api';

const AuthContext = createContext();

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [token, setToken] = useState(localStorage.getItem('auth_token'));
  const [loading, setLoading] = useState(true);

  const API_BASE_URL = getApiUrl();

  // Vérifier le token au chargement
  useEffect(() => {
    if (token) {
      checkAuthStatus();
    } else {
      setLoading(false);
    }
  }, [token]);

  const checkAuthStatus = async () => {
    try {
      const response = await fetch(`${API_BASE_URL}/accounts/current-user/`, {
        headers: {
          'Authorization': `Token ${token}`,
        },
      });

      if (response.ok) {
        const userData = await response.json();
        setUser(userData);
      } else {
        // Token invalide
        logout();
      }
    } catch (error) {
      console.error('Erreur lors de la vérification du token:', error);
      logout();
    } finally {
      setLoading(false);
    }
  };

  const login = async (username, password) => {
    try {
      const response = await fetch(`${API_BASE_URL}/accounts/login/`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ username, password }),
      });

      if (response.ok) {
        const data = await response.json();
        const { token: newToken, user: userData } = data;
        
        setToken(newToken);
        setUser(userData);
        localStorage.setItem('auth_token', newToken);
        
        toast.success('Connexion réussie !');
        return { success: true };
      } else {
        const errorData = await response.json();
        // Extraire le message d'erreur depuis la réponse Django REST Framework
        let errorMessage = 'Erreur de connexion';
        
        if (errorData.non_field_errors && errorData.non_field_errors.length > 0) {
          errorMessage = errorData.non_field_errors[0];
        } else if (errorData.username && errorData.username.length > 0) {
          errorMessage = errorData.username[0];
        } else if (errorData.password && errorData.password.length > 0) {
          errorMessage = errorData.password[0];
        } else if (errorData.error) {
          errorMessage = errorData.error;
        }
        
        toast.error(errorMessage);
        return { success: false, error: errorMessage };
      }
    } catch (error) {
      console.error('Erreur lors de la connexion:', error);
      toast.error('Erreur de connexion');
      return { success: false, error: 'Erreur de connexion' };
    }
  };

  const register = async (userData) => {
    try {
      const response = await fetch(`${API_BASE_URL}/accounts/register/`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(userData),
      });

      if (response.ok) {
        const data = await response.json();
        const { token: newToken, user: newUser } = data;
        
        setToken(newToken);
        setUser(newUser);
        localStorage.setItem('auth_token', newToken);
        
        toast.success('Compte créé avec succès !');
        return { success: true };
      } else {
        let errorData = {};
        try {
          errorData = await response.json();
        } catch (e) {
          console.error('Impossible de parser la réponse d\'erreur:', e);
        }
        
        // Formater les erreurs de manière lisible
        let errorMessage = '';
        if (errorData.error || errorData.detail) {
          errorMessage = errorData.error || errorData.detail;
        } else if (typeof errorData === 'object') {
          // Si c'est un objet avec des erreurs par champ
          const errorMessages = [];
          for (const [field, messages] of Object.entries(errorData)) {
            if (Array.isArray(messages)) {
              errorMessages.push(`${field}: ${messages.join(', ')}`);
            } else {
              errorMessages.push(`${field}: ${messages}`);
            }
          }
          errorMessage = errorMessages.join('\n');
        } else {
          errorMessage = 'Erreur lors de l\'inscription';
        }
        
        toast.error(errorMessage);
        return { success: false, error: errorMessage };
      }
    } catch (error) {
      console.error('Erreur lors de l\'inscription:', error);
      toast.error('Erreur lors de l\'inscription');
      return { success: false, error: 'Erreur lors de l\'inscription' };
    }
  };

  const logout = async () => {
    try {
      if (token) {
        // Appeler l'API de déconnexion
        await fetch(`${API_BASE_URL}/accounts/logout/`, {
          method: 'POST',
          headers: {
            'Authorization': `Token ${token}`,
          },
        });
      }
    } catch (error) {
      console.error('Erreur lors de la déconnexion:', error);
    } finally {
      // Nettoyer le state local
      setToken(null);
      setUser(null);
      localStorage.removeItem('auth_token');
      toast.success('Déconnexion réussie');
    }
  };

  const updateProfile = async (profileData) => {
    try {
      const response = await fetch(`${API_BASE_URL}/profile/update/`, {
        method: 'PATCH',
        headers: {
          'Authorization': `Token ${token}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(profileData),
      });

      if (response.ok) {
        const updatedProfile = await response.json();
        setUser(prev => ({ ...prev, profile: updatedProfile }));
        toast.success('Profil mis à jour !');
        return { success: true };
      } else {
        const errorData = await response.json();
        toast.error(errorData.error || 'Erreur lors de la mise à jour');
        return { success: false, error: errorData.error };
      }
    } catch (error) {
      console.error('Erreur lors de la mise à jour du profil:', error);
      toast.error('Erreur lors de la mise à jour du profil');
      return { success: false, error: 'Erreur lors de la mise à jour du profil' };
    }
  };

  const value = {
    user,
    token,
    loading,
    login,
    register,
    logout,
    updateProfile,
    isAuthenticated: !!token,
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};









